// Register Top module auto-generated by `reggen`

module midi_ctrl (
  input logic clk_100mhz_i,
  output wire midi_rx // MIDI RX line connected to the midi parser
);

  localparam int BAUD_RATE = 31250; 
  localparam int CLOCK_FREQ = 100_000_000; // 100 MHz
  localparam int BIT_TICKS = CLOCK_FREQ / BAUD_RATE; // 1600 * 2

  // Reset and clock generation
  // --------------------------

  logic clk_i;

  task wait_cycles(input integer n_cycles);
    integer i;
    for (i = 0; i < n_cycles; i++) @(posedge clk_i);
  endtask

  logic midi_rx_buff;


  assign clk_i = clk_100mhz_i;
  assign midi_rx = midi_rx_buff;

	// Task to send a UART byte (LSB first, 8N1)
  task send_uart_byte(input byte data);
    int i;
    begin
      // Start bit (0)
      midi_rx_buff = 0;
      wait_cycles(BIT_TICKS);

      // 8 data bits (LSB first)
      for (i = 0; i <= 7; i++) begin
        midi_rx_buff = data[i];
        wait_cycles(BIT_TICKS);
      end

      // Stop bit (1)
      midi_rx_buff = 1;
      wait_cycles(BIT_TICKS);
      $display("Sent a byte.");
    end
  endtask

  logic [3:0] midi_cmd_p = '0; 
  initial begin
		// Idle line is high
    midi_rx_buff = 1;
    // for big LUTS:
    //wait_cycles(1500000);
    // for smaller LUTS:
    wait_cycles(700000);
    for (int i = 0; i < 10; i++) begin
      if (midi_cmd_p == 9) begin
        send_uart_byte(8'h80); // Note OFF command
        send_uart_byte(8'h45); // Note value
        send_uart_byte(8'h26); // Velocity
      end else if (midi_cmd_p == 1) begin
        // Set Decay = 60
        send_uart_byte(8'hB0);
        send_uart_byte(8'h4B); // CC 75 = Decay
        send_uart_byte(8'h60);
      end else if (midi_cmd_p == 2) begin
        // Set Sustain = 90
        send_uart_byte(8'hB0);
        send_uart_byte(8'h4C); // CC 76 = Sustain
        send_uart_byte(8'h50);
      end else if (midi_cmd_p == 3) begin
        // Set Release = 50
        send_uart_byte(8'hB0);
        send_uart_byte(8'h4D); // CC 77 = Release
        send_uart_byte(8'h50);
      end else if (midi_cmd_p == 4) begin
        // Set Attack = 40
        send_uart_byte(8'hB0); // CC on Channel 0
        send_uart_byte(8'h4A); // CC 74 = Attack
        send_uart_byte(8'h40); // Value = 40
      end else if (midi_cmd_p == 5) begin
        send_uart_byte(8'h90); // Note On command
        send_uart_byte(8'h45); // Note value
        send_uart_byte(8'h7F); // Velocity
      end else if (midi_cmd_p == 6) begin
        send_uart_byte(8'h91); // Note On command
        send_uart_byte(8'h19); // Note value
        send_uart_byte(8'h35); // Velocity
      end else if (midi_cmd_p == 7) begin
        // Set Echo ON
        send_uart_byte(8'hB0);
        send_uart_byte(8'h4E); // CC 78 = Echo
        send_uart_byte(8'h50);
      end else if (midi_cmd_p == 0) begin
        // Invalid input (missing data bytes)
        send_uart_byte(8'hB0);
        send_uart_byte(8'h5E); // CC 78 = Echo
      end else if (midi_cmd_p == 8) begin
        // Unsupported MIDI Event
        send_uart_byte(8'hB2);
        send_uart_byte(8'h5E); // CC 78 = Echo
        send_uart_byte(8'h50);
      end
      midi_cmd_p = midi_cmd_p + 1;
      wait_cycles(8000);
    end
    #10000000;  
    $finish;
  end

endmodule

